"use client";
import type { ReactNode } from "react";
import { useRef } from "react";
import "./dock.css";

export interface DockItem {
  label: string;
  icon: ReactNode;
  href?: string;
  onClick?: () => void;
  active?: boolean;
}
/** A row of icons that swell toward the pointer, like a desktop dock. */
export function Dock({ items, label = "Dock", className = "" }: { items: DockItem[]; label?: string; className?: string }) {
  const list = useRef<HTMLUListElement>(null);
  const magnify = (x: number | null) => {
    const reduce = matchMedia("(prefers-reduced-motion:reduce)").matches;
    for (const li of list.current?.children ?? []) {
      const el = li as HTMLElement;
      if (x === null || reduce) {
        el.style.setProperty("--forme-dock-scale", "1");
        continue;
      }
      const r = el.getBoundingClientRect();
      const d = (x - (r.left + r.width / 2)) / 90;
      el.style.setProperty("--forme-dock-scale", String(1 + 0.62 * Math.exp(-d * d)));
    }
  };
  return (
    <nav aria-label={label} className={`forme-dock ${className}`}>
      <ul ref={list} onPointerMove={(e) => e.pointerType === "mouse" && magnify(e.clientX)} onPointerLeave={() => magnify(null)}>
        {items.map((item) => {
          const inner = (
            <>
              <span className="forme-dock-icon" aria-hidden="true">
                {item.icon}
              </span>
              <span className="forme-dock-label">{item.label}</span>
            </>
          );
          return (
            <li key={item.label} data-active={item.active || undefined}>
              {item.href ? (
                <a href={item.href} aria-label={item.label} aria-current={item.active ? "page" : undefined}>
                  {inner}
                </a>
              ) : (
                <button type="button" aria-label={item.label} aria-pressed={item.active} onClick={item.onClick}>
                  {inner}
                </button>
              )}
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

.forme-dock {
  display: flex;
  justify-content: center;
}
.forme-dock ul {
  display: inline-flex;
  align-items: flex-end;
  gap: 8px;
  height: 64px;
  margin: 0;
  padding: 0 10px 10px;
  border-radius: 22px;
  background: color-mix(in srgb, currentColor 7%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, currentColor 12%, transparent),
    0 18px 40px -18px #0006;
  backdrop-filter: blur(18px) saturate(1.4);
  -webkit-backdrop-filter: blur(18px) saturate(1.4);
  list-style: none;
}
.forme-dock li {
  --forme-dock-scale: 1;
  position: relative;
  width: calc(44px * var(--forme-dock-scale));
  height: calc(44px * var(--forme-dock-scale));
  transition:
    width 0.18s cubic-bezier(0.2, 0.8, 0.2, 1),
    height 0.18s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.forme-dock a,
.forme-dock button {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  border-radius: 28%;
  background: color-mix(in srgb, currentColor 10%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, currentColor 14%, transparent);
  color: inherit;
  cursor: pointer;
}
.forme-dock-icon {
  display: grid;
  width: 46%;
  height: 46%;
}
.forme-dock-icon svg {
  width: 100%;
  height: 100%;
}
.forme-dock-label {
  position: absolute;
  bottom: calc(100% + 10px);
  left: 50%;
  padding: 5px 9px;
  border-radius: 8px;
  background: #18181b;
  box-shadow: inset 0 0 0 1px #ffffff1f;
  color: #fafafa;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  opacity: 0;
  transform: translate(-50%, 4px);
  transition:
    opacity 0.15s,
    transform 0.15s;
  pointer-events: none;
}
.forme-dock li:hover .forme-dock-label,
.forme-dock li:focus-within .forme-dock-label {
  opacity: 1;
  transform: translate(-50%, 0);
}
.forme-dock li[data-active]::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -6px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  transform: translateX(-50%);
}
.forme-dock a:focus-visible,
.forme-dock button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .forme-dock li,
  .forme-dock-label {
    transition: none;
  }
}
